#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int countP = 0, countM = 0;
    for (int i = 0; i < n; i++) {
        int t;
        scanf("%d", &t);
        if (t == 1) countP++;
        else countM++;
    }

    int p, m;
    scanf("%d", &p);
    scanf("%d", &m);

    if (countP <= p && countM <= m)
        printf("S\n");
    else
        printf("N\n");

    return 0;
}
